Semi-pseudocode:


{noformat}type MenuItemId = number;
interface TraceIdParts {
    maybePimFeeDbId?: number;
    maybeCityFeeDbId?: number;
    maybeMenuSyncType?: 'city_fee' | 'city_fee_with_custom_sku' | 'custom_fee';
}
interface PimFee {
    id: number;
    sku: string;
    external_id: number;
    menu_sync_type?: string;
    // ... other PIM fields
}
interface LocalMenuFeeItem {
    id: MenuItemId;
    sku?: string;
}
interface CityFeeDefinition {
    id: number;
    // ... other DB columns
}
interface BatchOp {
    localItem: LocalMenuFeeItem;
    action: 'create' | 'update';
    payload: Partial<PimFee>;
}
interface BatchResult {
    localId: MenuItemId;
    success: boolean;
    sku?: string;
    error?: string;
}
interface SyncResolution {
    skuToMap: string;
    updateOp?: BatchOp;
}

// Mocks & context:
const logger = { error: (s: string, d?: any) => console.error(s, d) };
const hash = (x: any): number => 12345;
let getPimFeesFromApi: () => PimFee[];
let feesOf: (m: any) => LocalMenuFeeItem[];
let getCityFeeDefinitions: (ids: number[]) => Promise<CityFeeDefinition[]>;
let executeBatchToPim: (ops: BatchOp[]) => Promise<BatchResult[]>;

// In place of or amending PIMSyncService.getOrUpdateFees:
async function getOrUpdateFees(menu: any): Promise<Record<MenuItemId, string>> {
    const menuFees = feesOf(menu);
    const pimFees = getPimFeesFromApi();

    const { pimFeesById, pimFeesBySku, pimFeesByCityFeeSourceId } = indexPimFees(pimFees);
    const cityFeeDefsById = await fetchAndIndexCityFeeDefinitions(menuFees);

    const feeTraces = new Map<number, TraceIdParts>();
    for (const item of menuFees) {
        const t = parseFeeTraceId(item, cityFeeDefsById);
        feeTraces.set(item.id, t);
    }

    // Core logic for sync and matching local ID to SKU:
    const mapLocalIdToPimSku: Record<string, string> = {};
    const batchOps: BatchOp[] = [];
    for (const localFee of menuFees) {
        const trace = feeTraces.get(localFee.id)!;

        // Synced from PIM (has PIM DB ID):
        if (trace.maybePimFeeDbId !== undefined) {
            const pimFee = pimFeesById.get(trace.maybePimFeeDbId);

            if (pimFee) {
                const result = resolveSyncedFee(localFee, pimFee, trace);
                if (result) {
                    mapLocalIdToPimSku[localFee.id] = result.skuToMap;
                    if (result.updateOp) {
                        batchOps.push(result.updateOp);
                    }
                }
            } else {
                // Relatively rare case where city-level fee is disabled.
                logger.error(`PIM fee not found by ID: ${trace.maybePimFeeDbId}`);
            }
            continue;
        }

        // City-level fee (fee data source of truth = fee DB row)
        if (trace.maybeCityFeeDbId !== undefined) {
            const cityFeeDbId = trace.maybeCityFeeDbId;
            // We assume existence because parseFeeTraceId validated this.
            const cityFeeRow = cityFeeDefsById.get(cityFeeDbId)!;

            // No local SKU - blank slate case:
            if (!localFee.sku) {
                const existingPimFee = pimFeesByCityFeeSourceId.get(cityFeeDbId);
                if (existingPimFee) {
                    mapLocalIdToPimSku[localFee.id] = existingPimFee.sku;
                    localFee.sku = existingPimFee.sku;
                } else {
                    // Create using data from the DB Row.
                    // mapLocalIdToPimSku is updated further below, during reconciliation.
                    batchOps.push({
                        localItem: localFee,
                        action: 'create',
                        payload: {
                            ...mapCityRowToPimFields(cityFeeRow),
                            external_id: cityFeeDbId,
                            menu_sync_type: "city_fee"
                        }
                    });
                }
                continue;
            }

            // Has local SKU:
            const localSku = localFee.sku;
            mapLocalIdToPimSku[localFee.id] = localSku;
            const existingBySku = pimFeesBySku.get(localSku);
            if (existingBySku) {
                // Update the existing PIM fee:
                batchOps.push({
                    localItem: localFee,
                    action: 'update',
                    payload: {
                        id: existingBySku.id,
                        external_id: cityFeeDbId,
                        menu_sync_type: "city_fee_with_custom_sku",
                        ...mapLocalToPimFields(localFee)
                    }
                });
            } else {
                // Create a new PIM fee representing the city fee with custom SKU:
                batchOps.push({
                    localItem: localFee,
                    action: 'create',
                    payload: {
                        ...mapCityRowToPimFields(cityFeeRow),
                        external_id: cityFeeDbId,
                        menu_sync_type: "city_fee_with_custom_sku",
                        sku: localSku
                    }
                });
            }
            continue;
        }

        // Does not reference PIM fee, does not reference Menu city-level fee.
        // So must be a custom fee.
        if (localFee.sku) {
            const localSku = localFee.sku;
            mapLocalIdToPimSku[localFee.id] = localSku;

            const existingBySku = pimFeesBySku.get(localSku);
            if (existingBySku) {
                batchOps.push({
                    localItem: localFee,
                    action: 'update',
                    payload: {
                        id: existingBySku.id,
                        menu_sync_type: "custom_fee",
                        ...mapLocalToPimFields(localFee)
                    }
                });
            } else {
                batchOps.push({
                    localItem: localFee,
                    action: 'create',
                    payload: {
                        ...mapLocalToPimFields(localFee),
                        // Risk of collision here, but we have no better option.
                        external_id: hash(localSku),
                        menu_sync_type: "custom_fee",
                        sku: localSku
                    }
                });
            }
        } else {
            logger.error("Found Custom Fee without SKU - cannot sync to PIM.");
        }
    }

    // Updating PIM:
    if (batchOps.length > 0) {
        const results = await executeBatchToPim(batchOps);

        const opsByLocalId = new Map<MenuItemId, BatchOp>();
        for (const op of batchOps) {
            opsByLocalId.set(op.localItem.id, op);
        }

        for (const res of results) {
            if (res.success && res.sku) {
                mapLocalIdToPimSku[res.localId] = res.sku;
                const originalOp = opsByLocalId.get(res.localId);
                if (originalOp && !originalOp.localItem.sku) {
                    originalOp.localItem.sku = res.sku;
                }
            } else {
                logger.error(`Failed to sync fee ${res.localId}: ${res.error}`);
            }
        }
    }

    return mapLocalIdToPimSku;
}

function indexPimFees(pimFees: PimFee[]) {
    const pimFeesById = new Map<number, PimFee>();
    const pimFeesBySku = new Map<string, PimFee>();
    const pimFeesByCityFeeSourceId = new Map<number, PimFee>();

    for (const pf of pimFees) {
        pimFeesById.set(pf.id, pf);
        if (pf.sku) {
            pimFeesBySku.set(pf.sku, pf);
        }
        if (pf.menu_sync_type === "city_fee") {
            pimFeesByCityFeeSourceId.set(pf.external_id, pf);
        }
    }
    return { pimFeesById, pimFeesBySku, pimFeesByCityFeeSourceId };
}

async function fetchAndIndexCityFeeDefinitions(
    menuFees: LocalMenuFeeItem[]
): Promise<Map<number, CityFeeDefinition>> {
    const candidateCityFeeIds = new Set<number>();

    for (const item of menuFees) {
        const rawId = extractRawFeeDbIdFromTraceId(item);
        if (rawId !== undefined) {
            candidateCityFeeIds.add(rawId);
        }
    }

    const cityFeeDefsById = new Map<number, CityFeeDefinition>();
    if (candidateCityFeeIds.size > 0) {
        const rows = await getCityFeeDefinitions(Array.from(candidateCityFeeIds));
        for (const row of rows) {
            cityFeeDefsById.set(row.id, row);
        }
    }

    return cityFeeDefsById;
}

function resolveSyncedFee(
    local: LocalMenuFeeItem,
    pim: PimFee,
    trace: TraceIdParts
): SyncResolution | null {
    switch (trace.maybeMenuSyncType!) {
        case "city_fee":
            return { skuToMap: pim.sku };

        case "city_fee_with_custom_sku":
            if (!local.sku) {
                logger.error("Invariant violation: 'city_fee_with_custom_sku' but has no SKU.");
                return null;
            }
            // We treat the Menu data as the final source of truth for the SKU.
            return {
                skuToMap: local.sku,
                updateOp: (pim.sku !== local.sku) ? {
                    localItem: local,
                    action: 'update',
                    payload: { id: pim.id, sku: local.sku }
                } : undefined
            };

        case "custom_fee":
            if (!local.sku) {
                logger.error(`Invariant violation: 'custom_fee' but has no SKU.`);
                return null;
            }
            // We treat the Menu data as the final source of truth for the SKU.
            return {
                skuToMap: local.sku,
                updateOp: {
                    localItem: local,
                    action: 'update',
                    payload: {
                        id: pim.id,
                        sku: local.sku,
                        ...mapLocalToPimFields(local)
                    }
                }
            };

        default:
            logger.error(`Unknown sync type: ${trace.maybeMenuSyncType} for fee ${local.id}`);
            return null;
    }
}

